const { THROW } = require('./src/db');
const { getLog, resetLog } = require('./src/audit');
const ops = {
  deleteUser: require('./src/ops/deleteUser').deleteUser,
  refundOrder: require('./src/ops/refundOrder').refundOrder,
  banAccount: require('./src/ops/banAccount').banAccount,
  resetPassword: require('./src/ops/resetPassword').resetPassword,
  revokeToken: require('./src/ops/revokeToken').revokeToken,
  deleteFile: require('./src/ops/deleteFile').deleteFile,
};
let ok = true;
for (const [name, fn] of Object.entries(ops)) {
  resetLog();
  fn('actor-1', 'target-1');
  const e = getLog();
  const good = e.length === 1 && e[0].actor === 'actor-1' && e[0].action === name && e[0].target === 'target-1';
  if (!good) { ok = false; console.log('HAPPY FAIL', name, JSON.stringify(e)); }
  resetLog();
  let threw = false;
  try { fn('actor-1', THROW); } catch { threw = true; }
  if (!threw || getLog().length !== 0) { ok = false; console.log('FAILURE-PATH FAIL', name, threw, getLog().length); }
}
console.log(ok ? 'ALL 6 OPS: happy path logs one correct entry; failed mutation logs nothing' : 'FAILURES ABOVE');
